<script setup lang="ts">
import {computed,onMounted,ref,shallowRef} from 'vue';
import {unifiedWorkspace,unifiedKnowledge,unifiedLearning} from '../services';
import type {Output} from '../../shared/protocol/registry';
import type {DateSelectionInput} from '../../shared/workspace-contracts';
import DateRangeControl from '../components/DateRangeControl.vue';
import ReviewLineChart from '../components/ReviewLineChart.vue';
const props=defineProps<{deckId:string;overview?:boolean}>(),emit=defineEmits<{view:[cardId:string,eventId:string]}>();
const date=ref<DateSelectionInput>({range:'30'}),result=shallowRef<Output<'workspace.analytics'>>(),rows=ref<Output<'workspace.analytics'>['items']>([]),error=ref(''),busy=ref(false),tree=shallowRef<Output<'knowledge.tree.read'>>(),node=ref(''),mastery=shallowRef<Output<'learning.mastery.knowledge'>>();
const records=computed(()=>[...rows.value].reverse().map((r,i)=>({id:r.eventId,ordinal:i+1,createdAt:r.createdAt,selfScore:r.scoreTenths===null?null:r.scoreTenths/10,elapsedSeconds:r.elapsedSeconds,correct:r.objectiveCorrect,effective:true})));
async function load(more=false){busy.value=true;error.value='';try{const r=await unifiedWorkspace.analytics({deckId:props.deckId,date:date.value,cursor:more?result.value?.nextCursor:null});rows.value=more?[...rows.value,...r.items]:r.items;result.value=r;}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function knowledge(){busy.value=true;try{tree.value=await unifiedKnowledge.tree({deckId:props.deckId});}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function inspect(){mastery.value=undefined;if(!node.value)return;busy.value=true;try{mastery.value=await unifiedLearning.knowledgeMastery({deckId:props.deckId,nodeId:node.value,scope:'aggregate'});}catch(e){error.value=String(e);}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section :aria-label="overview?'卡片集概览':'学习分析'"><h2>{{overview?'卡片集概览':'学习分析'}}</h2><fieldset :disabled="busy"><legend>统计范围</legend><DateRangeControl v-model="date"/><button @click="load()">更新分析</button></fieldset><p v-if="error" role="alert">{{error}}</p><template v-if="result"><dl class="metrics"><div><dt>当前卡片</dt><dd>{{result.cardCount}}</dd></div><div><dt>范围内复盘</dt><dd>{{result.eventCount}}</dd></div><div><dt>平均自评</dt><dd>{{result.averageScoreTenths===null?'未记录':(result.averageScoreTenths/10).toFixed(1)}}</dd></div><div><dt>平均用时</dt><dd>{{result.averageElapsedSeconds===null?'未记录':result.averageElapsedSeconds.toFixed(1)+' 秒'}}</dd></div></dl><p>单选错题 {{result.cardsByMode.question}} · 问答记忆 {{result.cardsByMode.qa}} · 直接记忆 {{result.cardsByMode.direct}}</p><p>有自评记录 {{result.gradedCount}} 次 · 仅练习 {{result.practiceCount}} 次 · {{result.window.timeZone}}</p><p>缺失自评和用时不按零补齐；当前卡片按现所属卡片集统计，原始历史证据保持不变。</p>
 <template v-if="!overview"><ReviewLineChart :records="records" metric="selfScore" title="已加载记录 · 自评分" selected-id="" unified neutral @select="id=>{const r=rows.find(r=>r.eventId===id);if(r)emit('view',r.cardId,r.eventId)}"/><ReviewLineChart :records="records" metric="elapsedSeconds" title="已加载记录 · 用时" selected-id="" unified neutral @select="id=>{const r=rows.find(r=>r.eventId===id);if(r)emit('view',r.cardId,r.eventId)}"/></template>
 <section aria-label="复盘记录列表"><h3>最近复盘</h3><button v-for="r in rows" :key="r.eventId" :disabled="busy" @click="emit('view',r.cardId,r.eventId)">{{r.title||'未命名卡片'}} · {{new Date(r.createdAt).toLocaleString('zh-CN')}} · {{r.scoreTenths===null?'未记录':(r.scoreTenths/10).toFixed(1)+' 分'}}</button><p v-if="!rows.length">此范围没有复盘记录。</p><button v-if="result.nextCursor" :disabled="busy" @click="load(true)">更多复盘记录</button></section></template>
 <details v-if="!overview"><summary>知识点综合掌握度</summary><button :disabled="busy" @click="knowledge">读取知识点</button><label v-if="tree">选择知识点<select v-model="node" aria-label="分析知识点" :disabled="busy" @change="inspect"><option value="">请选择</option><option v-for="n in tree.nodes" :key="n.nodeId" :value="n.nodeId">{{n.name}}</option></select></label><p v-if="mastery">{{mastery.status==='pending'?'当前周期待评估':mastery.status==='unseen'?'尚未复盘':mastery.observations+' 次观察'}} · 关联 {{mastery.cardIds.length}} 张卡片</p></details>
 </section></template>
<style scoped>section{max-width:1100px;margin:auto}fieldset{border:1px solid var(--line,#ddd);border-radius:10px;padding:12px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:24px 0}.metrics div{padding:14px;background:var(--panel,#fff);border:1px solid var(--line,#ddd);border-radius:10px}dt{font-size:13px}dd{margin:6px 0 0;font-size:24px}button{margin:6px}section[aria-label=复盘记录列表] button{display:block;text-align:left}select{max-width:100%}@media(max-width:760px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
